package cl.duoc.bancoxyz.accounts.event;
import cl.duoc.bancoxyz.accounts.model.ProcessedEvent; import cl.duoc.bancoxyz.accounts.repository.ProcessedEventRepository; import cl.duoc.bancoxyz.accounts.service.BankAccountService; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @ConditionalOnProperty(name="app.kafka.enabled",havingValue="true")
public class PaymentEventConsumer { private final ObjectMapper mapper; private final ProcessedEventRepository processed; private final BankAccountService accounts; public PaymentEventConsumer(ObjectMapper mapper,ProcessedEventRepository processed,BankAccountService accounts){this.mapper=mapper;this.processed=processed;this.accounts=accounts;}
    @KafkaListener(topics="pagos.realizados",groupId="account-service") @Transactional public void consume(String json)throws Exception{PaymentCompletedEvent e=mapper.readValue(json,PaymentCompletedEvent.class);if(processed.existsById(e.eventId()))return;switch(e.type()){case "TRANSFER"->{accounts.debit(e.sourceAccountId(),e.amount());accounts.credit(e.targetAccountId(),e.amount());}case "WITHDRAWAL"->accounts.debit(e.sourceAccountId(),e.amount());case "DEPOSIT"->accounts.credit(e.targetAccountId(),e.amount());default->throw new IllegalArgumentException("Tipo de pago no soportado");}processed.save(new ProcessedEvent(e.eventId()));}
}
